\begin{tikzpicture}[line cap=round,line join=round,scale=1.0]
% three panels
\draw[thick] (-4.2,-1.6) rectangle (-1.4,1.6);
\draw[thick] (-1.0,-1.6) rectangle (1.8,1.6);
\draw[thick] (2.2,-1.6) rectangle (5.0,1.6);
\node[font=\small] at (-2.8,1.85) {Mirror P};
\node[font=\small] at (0.4,1.85) {Mirror Q};
\node[font=\small] at (3.6,1.85) {Mirror R};
% P: same-size erect stick figure (plane)
\draw[thick] (-3.5,0.2)--(-3.5,-0.9); \fill (-3.5,0.35) circle (0.12);
\node[font=\footnotesize] at (-2.8,-1.35) {image = object size, erect};
% Q: enlarged erect (concave, close)
\draw[thick] (-0.1,0.4)--(-0.1,-1.0); \fill (-0.1,0.55) circle (0.16);
\node[font=\footnotesize] at (0.4,-1.35) {larger, erect};
% R: diminished erect (convex)
\draw[thick] (3.3,0.05)--(3.3,-0.55); \fill (3.3,0.15) circle (0.08);
\node[font=\footnotesize] at (3.6,-1.35) {smaller, erect};
\end{tikzpicture}
